#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

struct DSU {
    int n;
    int components;
    vector<int> parent;
    vector<int> sz;

    DSU(int n) : n(n), components(n), parent(n + 1), sz(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }

    bool unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            if (sz[root_i] < sz[root_j])
                swap(root_i, root_j);
            parent[root_j] = root_i;
            sz[root_i] += sz[root_j];
            components--;
            return true;
        }
        return false;
    }
};

struct Edge {
    int u, v, type;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;

    vector<Edge> roads;
    DSU dsu(n);

    bool water_cycle = false;
    int road_count = 0;

    for (int i = 0; i < m; ++i) {
        int u, v, t;
        cin >> u >> v >> t;
        if (t == 1) {
            if (!dsu.unite(u, v)) {
                water_cycle = true;
            }
        } else {
            roads.push_back({u, v, t});
            road_count++;
        }
    }

    if (water_cycle) {
        cout << "N\n";
        return 0;
    }

    int c_water = dsu.components;

    for (const auto& edge : roads) {
        dsu.unite(edge.u, edge.v);
    }

    int c_total = dsu.components;

    int max_roads_kept = c_water - c_total;
    int min_roads_removed = road_count - max_roads_kept;

    if (min_roads_removed <= k) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
